SELECT CASE WHEN CAST(CASE WHEN ABS(CAST(COALESCE(SUM("Sales"."salesamount"), CAST(NULL AS DECIMAL(1, 1))) / NULLIF(NULLIF(COUNT(1), 0), 0) AS DECIMAL(38, 2))) >= 10000000000000000 OR ABS(CAST(COALESCE(SUM("Sales"."salesamount"), CAST(NULL AS DECIMAL(1, 1))) / NULLIF(NULLIF(COUNT(1), 0), 0) AS DOUBLE)) >= CAST('20000000000000000' AS DOUBLE) THEN 'OBSL: a value past DECIMAL(18, 2)' ELSE '0' END AS INT) = 0 THEN CAST(COALESCE(SUM("Sales"."salesamount"), CAST(NULL AS DECIMAL(1, 1))) / NULLIF(NULLIF(COUNT(1), 0), 0) AS DECIMAL(18, 2)) END AS "Average Sale"
FROM "orionbelt_1"."sales" AS "Sales"
